-- Forward repair discovered in rollback-only QA. Safe on the original or already-corrected function.
do $patch$ declare f text; old_text text:=$old$if exists(with delta as(select (l->>'account_id')::uuid aid,sum((l->>'debit_cents')::numeric-(l->>'credit_cents')::numeric) net from jsonb_array_elements(r.plans)e cross join lateral jsonb_array_elements(e->'lines')l group by 1), current_tb as(select a.id,coalesce(sum(l.debit_cents-l.credit_cents) filter(where j.status='posted' and j.entry_date<=r.cutoff),0) net from clickbooks_us.accounts a left join clickbooks_us.journal_lines l on l.account_id=a.id left join clickbooks_us.journals j on j.id=l.journal_id where a.book_id=b.id group by a.id) select 1 from current_tb c left join delta d on d.aid=c.id left join jsonb_array_elements(r.expected_balances)e on e->>'account_id'=c.id::text where c.net+coalesce(d.net,0)<>coalesce((e->>'net_debit_cents')::numeric,0))$old$; new_text text:=$new$if exists(with delta as(select (plan_line.value->>'account_id')::uuid aid,sum((plan_line.value->>'debit_cents')::numeric-(plan_line.value->>'credit_cents')::numeric) net from jsonb_array_elements(r.plans) plan_row(value) cross join lateral jsonb_array_elements(plan_row.value->'lines') plan_line(value) group by 1), current_tb as(select ledger_account.id,coalesce(sum(ledger_line.debit_cents-ledger_line.credit_cents) filter(where ledger_journal.status='posted' and ledger_journal.entry_date<=r.cutoff),0) net from clickbooks_us.accounts ledger_account left join clickbooks_us.journal_lines ledger_line on ledger_line.account_id=ledger_account.id left join clickbooks_us.journals ledger_journal on ledger_journal.id=ledger_line.journal_id where ledger_account.book_id=b.id group by ledger_account.id) select 1 from current_tb tb_entry left join delta delta_entry on delta_entry.aid=tb_entry.id left join jsonb_array_elements(r.expected_balances) expected_row(value) on expected_row.value->>'account_id'=tb_entry.id::text where tb_entry.net+coalesce(delta_entry.net,0)<>coalesce((expected_row.value->>'net_debit_cents')::numeric,0))$new$; begin select pg_get_functiondef('clickbooks_us.validate_migration(uuid)'::regprocedure) into f; if strpos(f,old_text)>0 then execute replace(f,old_text,new_text); elsif strpos(f,new_text)=0 then raise exception 'CB_VALIDATOR_VERSION_MISMATCH'; end if; end $patch$;
